<?php declare(strict_types=1);require __DIR__.'/includes/config.php';$uid=ir_current_user_id();$q=$pdo->prepare('SELECT d.*,z.jmeno_kod,z.latinsky_nazev,c.name contact_name,c.company,c.email,c.phone,c.address contact_address,c.country FROM wp_ir2_documents d LEFT JOIN wp_ir2_zvirata z ON z.id=d.animal_id AND z.user_id=d.user_id LEFT JOIN wp_ir2_contacts c ON c.id=d.contact_id AND c.user_id=d.user_id WHERE d.id=? AND d.user_id=?');$q->execute([(int)($_GET['id']??0),$uid]);$d=$q->fetch();if(!$d){http_response_code(404);exit('Dokument nenalezen.');}$type=['purchase'=>'KUPNÍ SMLOUVA / PURCHASE AGREEMENT / KAUFVERTRAG','sale'=>'PRODEJNÍ SMLOUVA / SALES AGREEMENT / VERKAUFSVERTRAG','handover'=>'PŘEDÁVACÍ PROTOKOL / HANDOVER PROTOCOL / ÜBERGABEPROTOKOLL','origin'=>'POTVRZENÍ O PŮVODU / CERTIFICATE OF ORIGIN / HERKUNFTSNACHWEIS','transport'=>'PŘEVOZNÍ DOKUMENT / TRANSPORT DOCUMENT / TRANSPORTDOKUMENT','receipt'=>'POTVRZENÍ O PŘEVZETÍ / RECEIPT / EMPFANGSBESTÄTIGUNG','custom'=>'DOKUMENT / DOCUMENT / DOKUMENT'][$d['template_key']]??'DOKUMENT / DOCUMENT / DOKUMENT';function field(string $l,string $v=''):void{echo '<div class="field"><label>'.htmlspecialchars($l).'</label><div>'.($v!==''?htmlspecialchars($v):'&nbsp;').'</div></div>';}?><!doctype html><html lang="cs"><head><meta charset="utf-8"><title><?=htmlspecialchars($d['title'])?></title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{margin:0;background:#e9ecef;color:#17191b;font:12px Arial,Helvetica,sans-serif}.sheet{width:210mm;min-height:297mm;margin:12px auto;background:#fff;padding:16mm 17mm;box-shadow:0 8px 30px #0002}.toolbar{position:fixed;right:22px;top:18px}.toolbar button{padding:9px 14px}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #17191b;padding-bottom:13px}.brand h1{font-size:22px;letter-spacing:.7px;margin:0}.brand p{margin:5px 0 0;color:#666}.docno{text-align:right;color:#555}.title{text-align:center;margin:24px 0 18px}.title h2{font-size:17px;margin:0 0 5px}.title p{margin:0;color:#777}.section{margin-top:17px}.section-title{font-size:10px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase;border-bottom:1px solid #222;padding-bottom:5px;margin-bottom:8px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px 18px}.field{min-height:43px}.field label{display:block;font-size:9px;font-weight:700;color:#555;margin-bottom:4px}.field div{min-height:23px;border-bottom:1px solid #999;padding:4px 1px;font-size:12px}.animal{border:1px solid #bbb;padding:11px 12px;background:#fafafa}.bodytext{white-space:pre-wrap;line-height:1.55;border:1px solid #d0d0d0;padding:11px;min-height:65px}.lang h3{font-size:10px;letter-spacing:.8px;margin:12px 0 5px}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:36px;margin-top:38px}.signature{padding-top:28px;border-top:1px solid #777;text-align:center;font-size:9px}.foot{margin-top:24px;border-top:1px solid #ddd;padding-top:7px;color:#777;font-size:8px;display:flex;justify-content:space-between}@media print{body{background:#fff}.sheet{width:auto;min-height:0;margin:0;padding:0;box-shadow:none}.toolbar{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Tisk / uložit PDF</button></div><main class="sheet"><header class="head"><div class="brand"><h1>IR MANAGER</h1><p>Breeding documentation · IReptiles</p></div><div class="docno"><b><?=htmlspecialchars($d['title'])?></b><br>#<?=str_pad((string)$d['id'],6,'0',STR_PAD_LEFT)?><br><?=date('d.m.Y',strtotime($d['created_at']))?></div></header><div class="title"><h2><?=htmlspecialchars($type)?></h2><p>CZ · EN · DE</p></div><section class="section"><div class="section-title">Strany / Parties / Parteien</div><div class="grid2"><?php field('Prodávající / Seller / Verkäufer');field('Kupující / Buyer / Käufer',(string)($d['contact_name']??''));field('Adresa / Address / Anschrift',(string)($d['contact_address']??''));field('E-mail / Telefon / Phone',(string)trim(($d['email']??'').' · '.($d['phone']??''),' ·'));?></div></section><section class="section animal"><div class="section-title">Zvíře / Animal / Tier</div><div class="grid2"><?php field('Identifikace / Identification / Identifikation',(string)($d['jmeno_kod']??''));field('Druh / Species / Art',(string)($d['latinsky_nazev']??''));field('Kategorie / Category / Kategorie',(string)$d['category']);field('Datum / Date / Datum',date('d.m.Y'));?></div></section><?php if(str_contains($d['language_mode'],'CZ')&&$d['body_cs']):?><section class="section lang"><h3>ČESKY</h3><div class="bodytext"><?=nl2br(htmlspecialchars($d['body_cs']))?></div></section><?php endif?><?php if(str_contains($d['language_mode'],'EN')&&$d['body_en']):?><section class="section lang"><h3>ENGLISH</h3><div class="bodytext"><?=nl2br(htmlspecialchars($d['body_en']))?></div></section><?php endif?><?php if(str_contains($d['language_mode'],'DE')&&$d['body_de']):?><section class="section lang"><h3>DEUTSCH</h3><div class="bodytext"><?=nl2br(htmlspecialchars($d['body_de']))?></div></section><?php endif?><div class="signatures"><div class="signature">Prodávající / Seller / Verkäufer</div><div class="signature">Kupující / Buyer / Käufer</div></div><footer class="foot"><span>Vygenerováno v IR Manager</span><span>Dokument #<?=str_pad((string)$d['id'],6,'0',STR_PAD_LEFT)?></span></footer></main></body></html>
